insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_148'
from (values
('127.890.d.12.A',3,'A trainee learns what ''station'', ''section view'' and ''detail'' mean before reading a fuselage print. She is:','["identifying and using aircraft drawing terminology", "describing tires", "describing seats", "ignoring prints"]'::jsonb,0,'Drawing terms.','original'),
('127.890.d.12.A',4,'A ''section view'' on an aircraft drawing shows:','["the price", "an imaginary cut through the part to reveal its inside", "the owner", "the paint color"]'::jsonb,1,'Section view.','original'),
('127.890.d.12.B',3,'A mechanic studies a blueprint, a hydraulic schematic and a performance chart to plan a repair. She is:','["ignoring prints", "painting drawings", "interpreting aircraft drawings, blueprints, sketches, charts, graphs and system schematics", "guessing"]'::jsonb,2,'Interpreting prints.','original'),
('127.890.d.12.B',4,'A system schematic mainly shows:','["exact part colors", "the price list", "shipping dates", "how the parts of a system connect and work together"]'::jsonb,3,'Schematic.','original'),
('127.890.d.13.A',3,'A student learns that a thick solid line is an outline and a dashed line is a hidden edge on a print. She is:','["identifying and describing the meaning of lines and symbols used in an aircraft drawing", "describing seats", "ignoring lines", "describing tires"]'::jsonb,0,'Line meanings.','original'),
('127.890.d.13.A',4,'On a drawing, a dashed line normally shows:','["a break", "a hidden edge not visible from that view", "a cut line", "a center point"]'::jsonb,1,'Hidden line.','original'),
('127.890.d.13.B',3,'A machinist reads a drawing that says 2.500 with a plus or minus .005 tolerance. She is:','["guessing", "ignoring numbers", "interpreting dimensions used in an aircraft drawing", "painting numbers"]'::jsonb,2,'Dimensions.','original'),
('127.890.d.13.B',4,'A tolerance of plus or minus .005 inch means the size can:','["be double", "never vary", "be anything", "vary a little within that range"]'::jsonb,3,'Tolerance.','original'),
('127.890.d.13.C',3,'A mechanic checks the revision block to see that a drawing was updated after a bracket redesign. She is:','["identifying changes to aircraft drawings", "guessing", "painting blocks", "ignoring revisions"]'::jsonb,0,'Revisions.','original'),
('127.890.d.13.C',4,'The revision block on a drawing records:','["the paint code", "changes made to the drawing and their dates", "the weather", "the owner''s name"]'::jsonb,1,'Revision block.','original'),
('127.890.d.13.D',3,'A mechanic reads the notes on a bracket print that call out the aluminum alloy and temper required. She is:','["painting notes", "ignoring notes", "identifying material requirements indicated by an aircraft drawing", "guessing"]'::jsonb,2,'Material notes.','original'),
('127.890.d.13.D',4,'Using a different material than the one called out on the drawing is allowed only if it is:','["shinier", "lighter looking", "cheaper", "approved as an acceptable substitute"]'::jsonb,3,'Substitutes.','original'),
('127.890.d.14.A',3,'A technician reads the rule that says a mechanic needs recent experience to use his certificate and learns what he may and may not approve. She is:','["identifying recency of experience requirements, the privileges and limitations of mechanic certificates", "describing seats", "ignoring rules", "guessing"]'::jsonb,0,'Certificate rules.','original'),
('127.890.d.14.A',4,'Part 65 recency of experience requires a mechanic to have worked in the past:','["1 month for a year", "24 months for at least 6 months", "a week each year", "6 months for 24 months"]'::jsonb,1,'Recency.','original'),
('127.890.d.14.B',3,'A student looks up the legal definitions of ''maintenance'', ''preventive maintenance'', ''rebuilding'' and ''alteration'' in Part 1. She is:','["describing tires", "ignoring terms", "defining maintenance terminology as defined in 14 CFR", "describing seats"]'::jsonb,2,'Maintenance terms.','original'),
('127.890.d.14.B',4,'Under the regulations, ''maintenance'' includes:','["only painting", "only flying", "only fueling", "inspection, overhaul, repair, preservation and replacement of parts"]'::jsonb,3,'Maintenance includes.','original'),
('127.890.d.14.C',3,'A mechanic writes the work performed, the date and her signature and certificate number in the logbook before the aircraft goes back into service. She is:','["describing requirements for maintenance record entries for approval for return to service", "hiding work", "ignoring logs", "guessing"]'::jsonb,0,'Return to service entry.','original'),
('127.890.d.14.C',4,'A return-to-service entry must include the mechanic''s:','["favorite color", "signature, certificate number and type of certificate", "address of the owner", "hobby"]'::jsonb,1,'Entry content.','original'),
('127.890.d.14.D',3,'A shop follows the manufacturer''s specified methods and techniques when performing a repair, as the rule requires. They are:','["guessing", "using any method", "identifying compliance requirements for manufacturer-specified maintenance methods", "ignoring methods"]'::jsonb,2,'Methods compliance.','original'),
('127.890.d.14.D',4,'Using methods, techniques and practices acceptable to the FAA means following:','["personal habit", "a friend''s advice", "old memory", "the current manufacturer''s maintenance manual or other acceptable data"]'::jsonb,3,'Acceptable methods.','original'),
('127.890.d.14.E',3,'A student explains why a manufacturer''s maintenance manual and an FAA advisory circular are sources of approved or acceptable data. She is:','["explaining FAA-approved maintenance data, including maintenance manuals and other maintenance publications", "describing seats", "ignoring manuals", "describing tires"]'::jsonb,0,'Approved data.','original'),
('127.890.d.14.E',4,'Which of these is a source of FAA-approved maintenance data?','["A hangar rumor", "A manufacturer''s maintenance manual", "A social post", "An old magazine"]'::jsonb,1,'Manuals.','original'),
('127.890.d.14.F',3,'A certificated mechanic moves and must report the new address to the FAA within the time allowed. She is:','["ignoring the rule", "hiding the move", "describing mechanic change of address notification procedures", "guessing"]'::jsonb,2,'Address change.','original'),
('127.890.d.14.F',4,'A certificate holder who moves must notify the FAA of the new address within:','["never", "5 years", "1 year", "30 days"]'::jsonb,3,'30 days.','original'),
('127.890.d.15.A',3,'A student checks a 100-hour inspection log entry for the date, the total time in service and the required statement. She is:','["evaluating a 100-hour inspection aircraft maintenance record entry for accuracy", "ignoring entries", "painting logs", "guessing"]'::jsonb,0,'Check entry.','original'),
('127.890.d.15.A',4,'A 100-hour inspection entry must include the aircraft''s:','["paint code", "total time in service", "fuel price", "owner''s age"]'::jsonb,1,'Total time.','original'),
('127.890.d.15.B',3,'A mechanic looks up the aircraft specification and TCDS to find engine and propeller limits for her model. She is:','["describing seats", "guessing", "locating applicable FAA aircraft specifications and type certificate data sheets", "ignoring specs"]'::jsonb,2,'Find TCDS.','original'),
('127.890.d.15.B',4,'A TCDS gives the approved:','["insurance rates", "flight plans", "owner list", "limits and data for a type-certificated aircraft"]'::jsonb,3,'TCDS content.','original'),
('127.890.d.15.C',3,'A mechanic compares the colored arcs on an airspeed indicator to the limits in the flight manual and checks the placards. She is:','["determining the conformity of aircraft instrument range markings and placarding", "ignoring markings", "painting arcs", "guessing"]'::jsonb,0,'Range markings.','original'),
('127.890.d.15.C',4,'A white arc on an airspeed indicator usually marks the:','["caution range", "flap operating range", "never-exceed speed", "normal range"]'::jsonb,1,'White arc.','original'),
('127.890.d.15.D',3,'A mechanic uses an illustrated parts catalog to find the part number for a bracket by its figure and index number. She is:','["describing seats", "ignoring the catalog", "using a manufacturer''s illustrated parts catalog to locate specific part numbers", "guessing"]'::jsonb,2,'IPC.','original'),
('127.890.d.15.D',4,'An illustrated parts catalog shows parts:','["by size only", "by price only", "by color only", "in exploded views with part numbers"]'::jsonb,3,'Exploded view.','original'),
('127.890.d.15.E',3,'A mechanic asks whether replacing a wing spar is a major or minor repair using Appendix A of Part 43. She is:','["determining whether a given repair or alteration is major or minor", "guessing", "describing seats", "ignoring rules"]'::jsonb,0,'Major or minor.','original'),
('127.890.d.15.E',4,'A repair that could appreciably affect strength or airworthiness is generally:','["minor", "major", "cosmetic", "optional"]'::jsonb,1,'Major repair.','original'),
('127.890.d.15.F',3,'A student explains that a major repair needs approved data and a FAA Form 337, while a minor repair can use acceptable data. She is:','["avoiding data", "describing seats", "explaining the difference between approved data and acceptable data", "describing tires"]'::jsonb,2,'Approved vs acceptable.','original'),
('127.890.d.15.F',4,'A major repair is documented on:','["a postcard", "a receipt", "a sticker", "FAA Form 337"]'::jsonb,3,'Form 337.','original'),
('127.890.d.16.A',3,'A student sorts aluminum, steel and rubber lines and their size codes and fittings on a plumbing chart. She is:','["identifying rigid tubing and flexible hose materials, applications, sizes and fittings", "describing seats", "describing tires", "ignoring lines"]'::jsonb,0,'Lines and hoses.','original'),
('127.890.d.16.A',4,'The size of a rigid tube is usually given by its:','["length only", "outside diameter", "inside diameter only", "color"]'::jsonb,1,'Tube OD.','original'),
('127.890.d.16.B',3,'A mechanic reviews how to cut, flare and install tubing and how to inspect for kinks and chafing. She is:','["describing seats", "ignoring tubing", "describing rigid tubing and flexible hose fabrication, installation and inspection", "describing tires"]'::jsonb,2,'Fabrication.','original'),
('127.890.d.16.B',4,'A tube with a kink or deep scratch should be:','["tightened more", "ignored", "painted", "replaced"]'::jsonb,3,'Damaged tube.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_148'
from (values
('127.890.d.16.C',3,'A mechanic tightens a fitting to its value with a torque wrench and adds a stripe of torque seal across it. She is explaining:','["the importance of properly using a torque wrench and torque seal when securing fittings", "guessing tightness", "ignoring torque", "skipping marks"]'::jsonb,0,'Torque seal.','original'),
('127.890.d.16.C',4,'A torque seal stripe that is broken later shows that the fitting:','["is perfect", "has moved or been disturbed", "is new", "is dry"]'::jsonb,1,'Broken stripe.','original'),
('127.890.d.16.D',3,'A student reads that a leak in a high-pressure hydraulic line can inject fluid under the skin. She is:','["describing tires", "ignoring risk", "analyzing and describing the risks associated with high-pressure hydraulic system components", "describing seats"]'::jsonb,2,'Hydraulic risk.','original'),
('127.890.d.16.D',4,'Before loosening a high-pressure hydraulic fitting, a mechanic should:','["leave pressure on", "use a hammer", "stand close", "relieve system pressure first"]'::jsonb,3,'Relieve pressure.','original'),
('127.890.d.17.A',3,'A student cuts a piece of aluminum tube, bends it to the plan and makes a 37-degree flare on the end. She is:','["fabricating and installing a rigid line with a flare and a bend", "painting the tube", "ignoring the tube", "buying a tube"]'::jsonb,0,'Flare and bend.','original'),
('127.890.d.17.A',4,'An AN flare on a tube end has an angle of:','["180 degrees", "37 degrees", "90 degrees", "10 degrees"]'::jsonb,1,'37 degree.','original'),
('127.890.d.17.B',3,'A mechanic cuts a hose to length, installs end fittings and pressure tests it. She is:','["painting the hose", "buying a hose", "fabricating and installing a flexible hose", "ignoring the hose"]'::jsonb,2,'Hose fab.','original'),
('127.890.d.17.B',4,'A flexible hose should be installed without:','["any fittings", "any clamps", "any slack", "twisting or sharp bends"]'::jsonb,3,'No twist.','original'),
('127.890.d.17.C',3,'A mechanic checks lines and hoses for chafing, cracks, leaks and loose clamps. She is:','["performing a rigid line and flexible hose inspection", "ignoring lines", "cutting lines", "painting lines"]'::jsonb,0,'Line inspection.','original'),
('127.890.d.17.C',4,'A hose that shows cracking or hardening on its outside should be:','["painted", "replaced", "ignored", "stretched"]'::jsonb,1,'Aged hose.','original'),
('127.890.d.18.A',3,'A student reads the markings stamped on a bolt head and the color on a cotter pin tag to learn the material and size. She is:','["describing tires", "describing seats", "identifying and describing material markings and hardware markings commonly used in aviation", "ignoring marks"]'::jsonb,2,'Hardware marks.','original'),
('127.890.d.18.A',4,'An AN bolt with a raised dash on its head is usually:','["a brass bolt", "an aluminum bolt", "a plastic bolt", "a corrosion-resistant steel bolt"]'::jsonb,3,'AN bolt marks.','original'),
('127.890.d.18.B',3,'A mechanic checks that a steel bolt is not used in direct contact with magnesium so that galvanic corrosion is avoided. She is:','["comparing suitability and compatibility of materials and hardware used for maintenance", "describing seats", "ignoring compatibility", "guessing"]'::jsonb,0,'Compatibility.','original'),
('127.890.d.18.B',4,'Dissimilar metals in contact can cause:','["brighter color", "galvanic corrosion", "cooler parts", "lower weight"]'::jsonb,1,'Galvanic.','original'),
('127.890.d.18.C',3,'A student labels arrows on a wing spar showing tension, compression, torsion, shear and bending. She is:','["describing seats", "ignoring forces", "explaining forces placed on aircraft materials, including tension, compression, torsion, shear and bending", "describing tires"]'::jsonb,2,'Stresses.','original'),
('127.890.d.18.C',4,'A force that tries to twist a part is called:','["shear", "tension", "compression", "torsion"]'::jsonb,3,'Torsion.','original'),
('127.890.d.18.D',3,'A mechanic double-twists safety wire across bolt heads so that the wire pulls each bolt tight. She is:','["identifying safety wire and safety clip requirements and techniques", "ignoring wire", "guessing", "painting wire"]'::jsonb,0,'Safety wire.','original'),
('127.890.d.18.D',4,'Safety wire is routed so that it pulls the nut or bolt in the direction of:','["loosening", "tightening", "no direction", "any direction"]'::jsonb,1,'Wire direction.','original'),
('127.890.d.18.E',3,'A mechanic passes a cotter pin through a castle nut and bends the legs around the bolt end. She is:','["painting pins", "guessing", "identifying cotter pin requirements and techniques", "ignoring pins"]'::jsonb,2,'Cotter pins.','original'),
('127.890.d.18.E',4,'A cotter pin is installed in a castle nut to:','["cool the bolt", "add weight", "add color", "keep the nut from backing off"]'::jsonb,3,'Cotter purpose.','original'),
('127.890.d.18.F',3,'A student learns how to read a micrometer to a thousandth of an inch and how to zero it. She is:','["describing precision measurement tools, principles and procedures", "describing tires", "describing seats", "ignoring tools"]'::jsonb,0,'Micrometer.','original'),
('127.890.d.18.F',4,'A technician needs to check the thickness of a sheet-metal skin to within a thousandth of an inch. Which tool fits best?','["A bathroom scale", "A micrometer", "A yardstick", "A thermometer"]'::jsonb,1,'Micrometer for thin stock.','original'),
('127.890.d.18.G',3,'A student cleans the joint, chooses rosin-core solder and applies flux before soldering a wire to a terminal. She is:','["guessing", "ignoring flux", "explaining soldering preparation, types of solder and flux usage", "describing seats"]'::jsonb,2,'Soldering.','original'),
('127.890.d.18.G',4,'Flux is used in soldering to:','["color the joint", "cool the iron", "add weight", "clean the surface so that the solder bonds"]'::jsonb,3,'Flux.','original'),
('127.890.d.18.H',3,'A student studies why a torque wrench reading matters and how the tool''s length or an extension changes the reading. She is:','["analyzing torquing tools, principles and procedures and the relationship between torque and fastener tension", "describing seats", "describing tires", "ignoring torque"]'::jsonb,0,'Torque theory.','original'),
('127.890.d.18.H',4,'Over-torquing a bolt can:','["cool the joint", "stretch or damage the bolt", "reduce friction", "help the joint"]'::jsonb,1,'Over-torque.','original'),
('127.890.d.18.I',3,'A student compares a smooth, even weld bead with one that has cracks and undercut along its edge. She is:','["describing seats", "describing tires", "differentiating between the characteristics of acceptable and unacceptable welds", "ignoring welds"]'::jsonb,2,'Weld quality.','original'),
('127.890.d.18.I',4,'A crack running through a weld bead makes the weld:','["stronger", "acceptable", "finished", "unacceptable"]'::jsonb,3,'Weld crack.','original'),
('127.890.d.19.A',3,'A mechanic picks the right bolts, turnbuckle barrels, washers and nuts from the parts catalog for a control cable repair. She is:','["selecting aircraft materials and hardware such as bolts, turnbuckles, washers and nuts", "using any hardware", "guessing", "ignoring the catalog"]'::jsonb,0,'Select hardware.','original'),
('127.890.d.19.A',4,'The bolt used on a primary structure should match:','["whatever is handy", "the manufacturer''s specified part and grade", "the cheapest", "any color"]'::jsonb,1,'Right bolt.','original'),
('127.890.d.19.B',3,'A mechanic safety-wires a row of bolts in a pattern with a neat twist. She is:','["painting bolts", "ignoring wire", "installing safety wire on hardware such as nuts, bolts and turnbuckles", "cutting bolts"]'::jsonb,2,'Wire install.','original'),
('127.890.d.19.B',4,'After safety-wiring a bolt, the pigtail end is:','["left sharp", "cut off flush", "left long", "bent back or tucked so that it does not snag"]'::jsonb,3,'Pigtail.','original'),
('127.890.d.19.C',3,'A mechanic places a new cotter pin through the hole in a clevis bolt and bends the legs. She is:','["installing cotter pins on hardware such as nuts and bolts", "cutting pins", "ignoring pins", "painting pins"]'::jsonb,0,'Cotter install.','original'),
('127.890.d.19.C',4,'A used cotter pin should generally not be:','["bent", "reused", "inspected", "measured"]'::jsonb,1,'No reuse.','original'),
('127.890.d.19.D',3,'A mechanic checks a micrometer against a gauge block and writes the date and result in the tool log. She is:','["painting the tool", "guessing", "checking for proper calibration of a precision-measurement tool and recording precision measurements", "ignoring calibration"]'::jsonb,2,'Calibration.','original'),
('127.890.d.19.D',4,'A precision tool should be calibrated on a schedule so that its readings:','["stay hidden", "become random", "become larger", "remain accurate"]'::jsonb,3,'Why calibrate.','original'),
('127.890.d.19.E',3,'A mechanic finds the torque in the maintenance manual and sets the wrench before tightening the bolts. She is:','["determining required torque values and properly torquing aircraft hardware", "ignoring torque", "tightening by feel", "guessing torque"]'::jsonb,0,'Set torque.','original'),
('127.890.d.19.E',4,'Torque values for a bolt should come from:','["a guess", "the maintenance manual for that application", "a friend", "the nearest toolbox"]'::jsonb,1,'Torque source.','original'),
('127.890.d.19.F',3,'A mechanic checks a weld on an engine mount for cracks, porosity and undercut and decides whether to accept it. She is:','["painting welds", "ignoring welds", "inspecting welds and differentiating between acceptable and unacceptable welds", "guessing"]'::jsonb,2,'Weld inspection.','original'),
('127.890.d.19.F',4,'A weld with porosity (tiny holes) and cracks should be:','["ignored", "accepted", "painted", "rejected and reworked"]'::jsonb,3,'Weld reject.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
